"""Contract tests for Gemini Call 2 (Adjudicate) input and output schemas.

Authority: docs/architecture/C-gemini-architecture.md §53-C, ADR-005
"""

from __future__ import annotations

import json

import pytest
from pydantic import ValidationError

from backend.staymad.llm.deterministic_client import DeterministicGeminiClient
from backend.staymad.llm.schemas import (
    AdjudicateDecision,
    AdjudicateInput,
    AdjudicateResponse,
    AnchorSummary,
    CandidateArticleInput,
)


def test_gemini_adjudicate_json_schema_structure():
    """Verify JSON schema generated by Pydantic conforms to C-gemini-architecture.md §53-C."""
    schema = AdjudicateResponse.model_json_schema()

    assert schema["type"] == "object"
    props = schema["properties"]

    assert "schema_version" in props
    assert "decisions" in props
    assert "suggested_event_headline" in props

    # Check decision item schema
    decision_schema = AdjudicateDecision.model_json_schema()
    dec_props = decision_schema["properties"]
    assert "article_version_id" in dec_props
    assert "decision" in dec_props
    assert "decision_reason_codes" in dec_props
    assert "confidence" in dec_props

    decision_field = dec_props["decision"]
    assert "enum" in decision_field
    assert set(decision_field["enum"]) == {
        "SAME_EVENT",
        "RELATED_EVENT",
        "SEPARATE_EVENT",
        "NEEDS_REVIEW",
    }


def test_adjudicate_decision_confidence_bounds():
    """Confidence must be bounded between 0.0 and 1.0."""
    valid_decision = AdjudicateDecision(
        article_version_id="11111111-2222-3333-4444-555555555555",
        decision="SAME_EVENT",
        decision_reason_codes=["LOC_MATCH", "TIME_WITHIN_WINDOW"],
        confidence=0.88,
    )
    assert valid_decision.confidence == 0.88

    with pytest.raises(ValidationError):
        AdjudicateDecision(
            article_version_id="11111111-2222-3333-4444-555555555555",
            decision="SAME_EVENT",
            confidence=1.5,  # Exceeds max 1.0
        )

    with pytest.raises(ValidationError):
        AdjudicateDecision(
            article_version_id="11111111-2222-3333-4444-555555555555",
            decision="SAME_EVENT",
            confidence=-0.1,  # Below min 0.0
        )


def test_adjudicate_cache_key_deterministic():
    """Cache key must be deterministic and independent of candidate ID input order."""
    client = DeterministicGeminiClient()
    ids_order_a = ["uuid-3", "uuid-1", "uuid-2"]
    ids_order_b = ["uuid-1", "uuid-2", "uuid-3"]
    anchor_id = "anchor-event-001"

    key_a = client.compute_adjudicate_cache_key(ids_order_a, anchor_id)
    key_b = client.compute_adjudicate_cache_key(ids_order_b, anchor_id)

    assert key_a == key_b
    assert len(key_a) == 64  # sha256 hex length


def test_deterministic_client_adjudicate_contract():
    """Verify deterministic mock client satisfies Call Type 2 contract."""
    client = DeterministicGeminiClient()
    payload = AdjudicateInput(
        processing_run_id="run-123",
        anchor_event_id="anchor-456",
        anchor_summary=AnchorSummary(
            headline="Banjir Luapan Kali Ciliwung Rendam Jakarta Timur",
            category="DISASTER_AND_WEATHER",
            primary_location="Jakarta Timur",
            time_window_start="2026-10-10T08:00:00+07:00",
            time_window_end="2026-10-10T12:00:00+07:00",
            representative_claims=[
                "Kali Ciliwung meluap pada Sabtu pagi",
                "Lima kecamatan di Jakarta Timur terendam banjir",
            ],
        ),
        candidate_articles=[
            CandidateArticleInput(
                article_version_id="art-ver-1",
                source_tier="TIER_1",
                source_family="LKBN_ANTARA",
                title="Hujan Deras, Banjir Rendam 5 Kecamatan di Jakarta Timur",
                excerpt="Banjir akibat luapan Kali Ciliwung merendam Kampung Melayu dan Bidara Cina.",
                published_time="2026-10-10T08:45:00+07:00",
                primary_location_raw="Jakarta Timur",
                deterministic_score=0.85,
                deterministic_signals={
                    "location_match": True,
                    "time_delta_hours": 0.75,
                    "category_match": True,
                },
                top_claims=["Kali Ciliwung meluap merendam 5 kecamatan"],
            ),
            CandidateArticleInput(
                article_version_id="art-ver-2",
                source_tier="TIER_2",
                source_family="TRANSMEDIA",
                title="Aktivitas Merapi Meningkat, Muntahkan Awan Panas",
                excerpt="Gunung Merapi kembali meluncurkan awan panas guguran ke arah barat daya.",
                published_time="2026-10-10T09:00:00+07:00",
                primary_location_raw="Magelang",
                deterministic_score=0.10,
                deterministic_signals={
                    "location_match": False,
                    "loc_incompatible": True,
                    "time_delta_hours": 1.0,
                    "category_match": True,
                },
                top_claims=["Merapi meluncurkan awan panas"],
            ),
        ],
    )

    response = client.adjudicate(payload)
    assert isinstance(response, AdjudicateResponse)
    assert response.schema_version == "1.0"
    assert len(response.decisions) == 2

    d1 = response.decisions[0]
    assert d1.article_version_id == "art-ver-1"
    assert d1.decision == "SAME_EVENT"
    assert "LOC_MATCH" in d1.decision_reason_codes
    assert "CORROBORATED" in d1.decision_reason_codes
    assert d1.confidence >= 0.60

    d2 = response.decisions[1]
    assert d2.article_version_id == "art-ver-2"
    assert d2.decision == "SEPARATE_EVENT"
    assert "LOC_INCOMPATIBLE" in d2.decision_reason_codes

    # Ensure valid wire JSON
    raw_json = response.model_dump_json()
    parsed = json.loads(raw_json)
    assert parsed["schema_version"] == "1.0"
    assert len(parsed["decisions"]) == 2


def test_adjudicate_override_rule_low_confidence():
    """If decision is SAME_EVENT but confidence < 0.60, it MUST be overridden to NEEDS_REVIEW."""
    client = DeterministicGeminiClient()
    # Candidate with weak token overlap causing confidence < 0.60
    payload = AdjudicateInput(
        processing_run_id="run-override",
        anchor_summary=AnchorSummary(
            headline="Banjir Luapan Kali Ciliwung Jakarta Timur",
            category="DISASTER_AND_WEATHER",
            primary_location="Jakarta Timur",
        ),
        candidate_articles=[
            CandidateArticleInput(
                article_version_id="art-weak-match",
                source_tier="TIER_2",
                source_family="UNKNOWN",
                title="Genangan di sebagian wilayah timur ibu kota",
                excerpt="Beberapa titik air terpantau di Jakarta.",
                deterministic_score=0.55,  # In ambiguous zone
                deterministic_signals={"location_match": True},
            )
        ],
    )

    response = client.adjudicate(payload)
    dec = response.decisions[0]
    # Decision must NOT be confident SAME_EVENT when confidence was under 0.60
    assert dec.decision in ("NEEDS_REVIEW", "SEPARATE_EVENT")
    if dec.decision == "NEEDS_REVIEW":
        assert "AMBIGUOUS" in dec.decision_reason_codes
